<?php require_once __DIR__ . '/includes/db.php'; require_once __DIR__ . '/includes/functions.php'; $pdo=db(); $slug=$_GET['slug'] ?? 'community-survey'; $st=$pdo->prepare("SELECT * FROM questionnaires WHERE slug=? AND status='active'"); $st->execute([$slug]); $qnr=$st->fetch(); if(!$qnr) die('Questionnaire not found or closed.'); $st=$pdo->prepare('SELECT q.*, qq.is_required FROM questionnaire_questions qq JOIN questions q ON q.id=qq.question_id WHERE qq.questionnaire_id=? ORDER BY qq.sort_order,q.id'); $st->execute([$qnr['id']]); $questions=$st->fetchAll(); if($_SERVER['REQUEST_METHOD']==='POST'){ $email=filter_var($_POST['responder_email'] ?? '', FILTER_VALIDATE_EMAIL) ?: null; $pdo->prepare('INSERT INTO questionnaire_responses(questionnaire_id,responder_email) VALUES(?,?)')->execute([$qnr['id'],$email]); $rid=$pdo->lastInsertId(); foreach($questions as $q){$answer=$_POST['q_'.$q['id']] ?? ''; if(is_array($answer)) $answer=implode(', ', $answer); $pdo->prepare('INSERT INTO response_answers(response_id,question_id,answer_text) VALUES(?,?,?)')->execute([$rid,$q['id'],$answer]);} redirect('thank-you.php'); } ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/css/style.css"><title><?=h($qnr['title'])?></title></head><body><header class="site-header"><div class="logo"><span>taos</span>arts.org</div><nav class="nav"><a href="index.php">Home</a></nav></header><section class="section" style="max-width:880px;margin:auto"><h1><?=h($qnr['title'])?></h1><p><?=h($qnr['intro'])?></p><form method="post" class="panel"><div class="form-row"><label>Your email, optional</label><input type="email" name="responder_email"></div><?php foreach($questions as $q): $opts=json_decode($q['options_json'] ?? '[]', true) ?: []; ?><div class="form-row"><label><?=h($q['prompt'])?> <?= $q['is_required']?'*':'' ?></label><?php if($q['help_text']): ?><small><?=h($q['help_text'])?></small><?php endif; ?><?php if($q['question_type']==='textarea'): ?><textarea name="q_<?=$q['id']?>" <?=$q['is_required']?'required':''?>></textarea><?php elseif(in_array($q['question_type'],['select'])): ?><select name="q_<?=$q['id']?>" <?=$q['is_required']?'required':''?>><?php foreach($opts as $o): ?><option><?=h($o)?></option><?php endforeach; ?></select><?php elseif(in_array($q['question_type'],['checkbox','radio'])): ?><?php foreach($opts as $o): ?><label><input type="<?=$q['question_type']?>" name="q_<?=$q['id']?><?= $q['question_type']==='checkbox'?'[]':'' ?>" value="<?=h($o)?>"> <?=h($o)?></label><?php endforeach; ?><?php else: ?><input type="<?=h($q['question_type'])?>" name="q_<?=$q['id']?>" <?=$q['is_required']?'required':''?>><?php endif; ?></div><?php endforeach; ?><button class="btn">Submit</button></form></section></body></html>
